import React from 'react';
import { HashRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import FindSchemes from './pages/FindSchemes';
import SchemeDetails from './pages/SchemeDetails';
import Auth from './pages/Auth';
import HowItWorks from './pages/HowItWorks';
import FAQs from './pages/FAQs';
import Settings from './pages/Settings';
import SavedSchemes from './pages/SavedSchemes';
import ChatWidget from './components/ChatWidget';

// Helper to scroll to top on route change
const ScrollToTop = () => {
  const { pathname } = useLocation();
  React.useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const App: React.FC = () => {
  return (
    <Router>
      <ScrollToTop />
      <div className="flex flex-col min-h-screen">
        <Navbar />
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/saved-schemes" element={<SavedSchemes />} />
            <Route path="/find-schemes" element={<FindSchemes />} />
            <Route path="/scheme/:id" element={<SchemeDetails />} />
            <Route path="/auth" element={<Auth />} />
            <Route path="/how-it-works" element={<HowItWorks />} />
            <Route path="/faqs" element={<FAQs />} />
            <Route path="/settings" element={<Settings />} />
          </Routes>
        </main>
        <Footer />
        <ChatWidget />
      </div>
    </Router>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Search, User, Menu, X, ChevronRight, LogOut, Settings, ChevronDown, Bookmark } from 'lucide-react';
import { signOut } from 'firebase/auth';
import { auth } from '../lib/firebase';

const Navbar: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [user, setUser] = useState<any>(null);
  const profileRef = useRef<HTMLDivElement>(null);

  const isActive = (path: string) => location.pathname === path;

  useEffect(() => {
    const checkUser = () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (savedUser) {
        setUser(JSON.parse(savedUser));
      } else {
        setUser(null);
      }
    };

    checkUser();
    window.addEventListener('storage', checkUser);
    return () => window.removeEventListener('storage', checkUser);
  }, [location.pathname]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      localStorage.removeItem('gov_smart_user');
      setUser(null);
      setIsProfileOpen(false);
      navigate('/');
      window.dispatchEvent(new Event('storage'));
    } catch (err) {
      console.error("Error signing out: ", err);
    }
  };

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'Find Schemes', path: '/find-schemes' },
    { name: 'How It Works', path: '/how-it-works' },
    { name: 'FAQs', path: '/faqs' },
  ];

  const userDisplayName = user?.username || 'User';

  return (
    <nav className="bg-white border-b border-gray-100 sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20 items-center">

          <div className="flex-shrink-0 flex items-center">
            <Link to="/" className="flex items-center gap-3">
              <div className="bg-navy p-2 rounded-xl shadow-lg shadow-navy/10">
                <span className="text-white font-black text-xl tracking-tighter">GS</span>
              </div>
              <div className="hidden sm:block">
                <span className="text-navy font-bold text-xl block leading-tight">Gov-Smart</span>
                <span className="text-[10px] text-orange-500 font-bold uppercase tracking-wider block">AI-Powered Portal</span>
              </div>
            </Link>
          </div>

          <div className="hidden lg:flex flex-1 justify-center">
            <div className="flex items-center gap-x-10">
              {navLinks.map((link) => (
                <Link 
                  key={link.path}
                  to={link.path} 
                  className={`relative py-2 text-sm font-bold transition-all duration-300 ${
                    isActive(link.path) 
                    ? 'text-navy' 
                    : 'text-gray-400 hover:text-navy'
                  }`}
                >
                  {link.name}
                  {isActive(link.path) && (
                    <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-primary rounded-full animate-in fade-in zoom-in duration-300"></span>
                  )}
                </Link>
              ))}
            </div>
          </div>

          <div className="flex items-center gap-x-6">
            <div className="hidden md:flex items-center gap-x-6 pr-6 border-r border-gray-100">
              <button className="text-gray-400 hover:text-navy transition-colors" onClick={() => navigate('/find-schemes')}>
                <Search size={20} />
              </button>
            </div>

            {user ? (
              <div className="relative" ref={profileRef}>
                <button 
                  onClick={() => setIsProfileOpen(!isProfileOpen)}
                  className="flex items-center gap-2 p-1 bg-gray-50 rounded-full border border-gray-200 hover:border-orange-200 transition-all hover:bg-white group overflow-hidden"
                >
                  <div className="relative w-9 h-9 bg-navy rounded-full flex items-center justify-center text-white">
                    <User size={18} />
                    <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-green-500 rounded-full border-2 border-white shadow-sm"></div>
                  </div>
                  <ChevronDown size={14} className={`text-gray-400 mx-1.5 transition-transform ${isProfileOpen ? 'rotate-180' : ''}`} />
                </button>

                {isProfileOpen && (
                  <div className="absolute right-0 mt-3 w-64 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="p-5 bg-gray-50/50 border-b border-gray-100">
                      <p className="text-sm font-bold text-navy truncate">{userDisplayName}</p>
                      <p className="text-xs text-gray-400 truncate">{user.email}</p>
                    </div>
                    <div className="p-2">
                      <Link to="/saved-schemes" onClick={() => setIsProfileOpen(false)} className="flex items-center gap-3 px-4 py-3 text-sm font-semibold text-gray-600 hover:bg-gray-50 hover:text-navy rounded-xl transition-all">
                        <Bookmark size={18} /> Saved Schemes
                      </Link>
                      <Link to="/settings" onClick={() => setIsProfileOpen(false)} className="flex items-center gap-3 px-4 py-3 text-sm font-semibold text-gray-600 hover:bg-gray-50 hover:text-navy rounded-xl transition-all">
                        <Settings size={18} /> Profile Settings
                      </Link>
                      <hr className="my-2 border-gray-100" />
                      <button 
                        onClick={handleLogout}
                        className="w-full flex items-center gap-3 px-4 py-3 text-sm font-semibold text-red-500 hover:bg-red-50 rounded-xl transition-all"
                      >
                        <LogOut size={18} /> Sign Out
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <Link 
                to="/auth" 
                className="hidden sm:flex items-center gap-2 px-6 py-2.5 bg-navy text-white hover:bg-orange-primary font-bold text-sm rounded-xl transition-all duration-300 shadow-md shadow-navy/10"
              >
                <User size={18} />
                <span>Sign In</span>
              </Link>
            )}

            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="lg:hidden p-2 rounded-xl hover:bg-gray-100 text-navy transition-all"
            >
              {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>

      <div 
        className={`lg:hidden overflow-hidden transition-all duration-300 ease-in-out bg-white border-t border-gray-50 ${
          isMenuOpen ? 'max-h-[500px] opacity-100' : 'max-h-0 opacity-0'
        }`}
      >
        <div className="px-4 py-6 space-y-4">
          {navLinks.map((link) => (
            <Link 
              key={link.path}
              to={link.path}
              onClick={() => setIsMenuOpen(false)}
              className={`flex items-center justify-between p-4 rounded-2xl font-bold transition-all ${
                isActive(link.path) 
                ? 'bg-orange-50 text-orange-600' 
                : 'text-navy hover:bg-gray-50'
              }`}
            >
              {link.name}
              <ChevronRight size={18} className={isActive(link.path) ? 'opacity-100' : 'opacity-0'} />
            </Link>
          ))}
          {user && (
            <Link 
              to="/saved-schemes"
              onClick={() => setIsMenuOpen(false)}
              className="flex items-center justify-between p-4 rounded-2xl font-bold text-navy hover:bg-gray-50 transition-all"
            >
              Saved Schemes
              <Bookmark size={18} />
            </Link>
          )}
          <div className="pt-4 border-t border-gray-50">
            {user ? (
               <button 
                onClick={handleLogout}
                className="w-full flex items-center justify-center gap-2 p-4 bg-red-50 text-red-500 rounded-2xl font-bold hover:bg-red-100 transition-all"
              >
                <LogOut size={18} /> Sign Out
              </button>
            ) : (
              <Link 
                to="/auth"
                onClick={() => setIsMenuOpen(false)}
                className="w-full flex items-center justify-center gap-2 p-4 bg-navy text-white rounded-2xl font-bold hover:bg-orange-primary transition-all shadow-xl"
              >
                <User size={18} />
                Sign In to Your Account
              </Link>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Bookmark, ChevronLeft, ChevronRight, Search, Trash2, Clock, Zap } from 'lucide-react';
import { MOCK_SCHEMES } from '../constants';
import { Scheme } from '../types';

const SavedSchemes: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [savedSchemes, setSavedSchemes] = useState<Scheme[]>([]);

  useEffect(() => {
    const fetchSaved = async () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (!savedUser) {
        navigate('/auth');
        return;
      }

      const savedIds = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
      const filtered = MOCK_SCHEMES.filter(s => savedIds.includes(s.id));
      setSavedSchemes(filtered);
      setLoading(false);
    };

    fetchSaved();
  }, [navigate]);

  const removeScheme = (id: string) => {
    const current = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
    const updated = current.filter((sid: string) => sid !== id);
    localStorage.setItem('saved_schemes', JSON.stringify(updated));
    setSavedSchemes(prev => prev.filter(s => s.id !== id));
    window.dispatchEvent(new Event('storage'));
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="w-10 h-10 border-2 border-orange-500 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fafb] pb-24">
      <div className="bg-white border-b sticky top-20 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <Link to="/" className="inline-flex items-center gap-2 text-sm font-bold text-gray-400 hover:text-navy transition-all">
              <ChevronLeft size={18} /> Back to Home
            </Link>
            <div className="flex items-center gap-2 px-4 py-1.5 bg-blue-50 text-blue-700 rounded-full text-xs font-bold border border-blue-100">
              <Bookmark size={14} /> {savedSchemes.length} Saved Schemes
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-12">
        <div className="mb-12">
          <h1 className="text-4xl font-extrabold text-navy mb-4 tracking-tight">Saved for Later</h1>
          <p className="text-gray-500 max-w-2xl">Quickly access the schemes you've bookmarked. Review eligibility requirements and start your applications when you're ready.</p>
        </div>

        {savedSchemes.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {savedSchemes.map((scheme) => (
              <div 
                key={scheme.id} 
                className="bg-white rounded-3xl border border-gray-100 hover:border-orange-200 hover:shadow-2xl transition-all group overflow-hidden flex flex-col h-full"
              >
                <div className="p-8 flex-grow">
                  <div className="flex justify-between items-start mb-6">
                    <div className="flex flex-wrap gap-2">
                      <span className="px-3 py-1 bg-green-50 text-green-700 text-[10px] font-black uppercase rounded-md tracking-widest">{scheme.category}</span>
                      <span className="px-3 py-1 bg-blue-50 text-blue-700 text-[10px] font-black uppercase rounded-md tracking-widest">{scheme.level}</span>
                    </div>
                    <button 
                      onClick={() => removeScheme(scheme.id)}
                      className="text-gray-300 hover:text-red-500 transition-colors p-2 rounded-xl hover:bg-red-50"
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                  <h3 className="text-xl font-bold text-navy mb-4 group-hover:text-orange-600 transition-colors line-clamp-2 leading-tight">{scheme.title}</h3>
                  <p className="text-sm text-gray-500 leading-relaxed line-clamp-3 mb-6">{scheme.description}</p>

                  <div className="flex items-center gap-4 text-xs text-gray-400 font-bold mb-4">
                    <div className="flex items-center gap-1.5">
                      <Clock size={14} /> {scheme.updatedAt}
                    </div>
                    <div className="flex items-center gap-1.5 text-orange-500">
                      <Zap size={14} fill="currentColor" /> AI Score: 98%
                    </div>
                  </div>
                </div>

                <div className="px-8 pb-8 pt-4 border-t border-gray-50 bg-gray-50/50">
                  <button 
                    onClick={() => navigate(`/scheme/${scheme.id}`)}
                    className="w-full py-4 bg-white border-2 border-gray-100 text-navy font-extrabold rounded-2xl flex items-center justify-center gap-2 hover:bg-orange-primary hover:text-white hover:border-orange-primary transition-all active:scale-[0.98]"
                  >
                    View & Apply <ChevronRight size={18} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="bg-white rounded-[3rem] p-24 text-center border border-dashed border-gray-200 shadow-sm">
            <div className="w-24 h-24 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-8 text-gray-200">
              <Bookmark size={48} />
            </div>
            <h3 className="text-3xl font-extrabold text-navy mb-4">No saved schemes yet</h3>
            <p className="text-gray-400 max-w-md mx-auto mb-10 text-lg">Browse the portal and bookmark schemes you're interested in to see them here.</p>
            <Link 
              to="/find-schemes" 
              className="inline-flex items-center gap-2 px-10 py-5 bg-navy text-white hover:bg-orange-primary font-bold rounded-2xl transition-all shadow-xl shadow-navy/10"
            >
              Start Discovering <Search size={20} />
            </Link>
          </div>
        )}
      </div>
    </div>
  );
};

export default SavedSchemes;

