              <div className="flex flex-col">
                <span className="text-2xl font-black text-[#1e293b] leading-none mb-1">{stat.value}</span>
                <span className="text-[11px] font-bold text-gray-400 uppercase tracking-widest">{stat.label}</span>
              </div>
            </div>
          ))}
        </div>

        {/* Profile Completion Horizontal Widget */}
        <div className="bg-white rounded-2xl p-8 border border-gray-100 shadow-sm mb-12">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8">
            <div className="flex items-center gap-6 flex-1">
              <div className="w-12 h-12 bg-orange-50 text-orange-600 rounded-full flex items-center justify-center shrink-0">
                <AlertCircle size={24} />
              </div>
              <div className="flex-1">
                <h3 className="text-lg font-bold text-[#1e293b] mb-1">Complete your profile for better matches</h3>
                <p className="text-sm text-gray-500 mb-4 font-medium">Fill in your details to discover more schemes you're eligible for</p>
