                    isActive(link.path) 
                    ? 'text-navy' 
                    : 'text-gray-400 hover:text-navy'
                  }`}
                >
                  {link.name}
                  {isActive(link.path) && (
                    <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-primary rounded-full animate-in fade-in zoom-in duration-300"></span>
